mapper.select:
SELECT role_id
FROM sys_user_role
WHERE tenant_id = #{tenantId}
  AND user_id = #{userId}
ORDER BY role_id

mapper.delete:
DELETE FROM sys_user_role
WHERE tenant_id = #{tenantId}
  AND user_id = #{userId}

mapper.select:
SELECT COUNT(*)
FROM sys_user_role
WHERE tenant_id = #{tenantId}
  AND role_id = #{roleId}

SELECT DISTINCT user_id
FROM sys_user_role
WHERE tenant_id = #{tenantId}
  AND role_id = #{roleId}
ORDER BY user_id
